INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('804', 'mbe', 'mbe_0804', 'prompt_1118', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '14', '', 'In May, Tina moved into and began paying a monthly rental of $200 for an apartment in a ten-unit apartment building owned by Lulu. The hallways and stairwells of the building needed repair. Lulu refused to undertake those repairs, even after Tina requested she do so. Therefore, in late August, Tina met with the other tenants and discussed with them the tenants'' legal options against Lulu for failure to make repairs. When Tina paid September''s rent, Lulu notified Tina that beginning in October, Tina''s rent would be $400 per month. When Tina protested that all of the other tenants were paying $200 per month, Lulu gave Tina the statutorily-required 30-day notice to vacate the apartment. If Tina prevails in a lawsuit contesting the termination of her tenancy, the most likely reason for her victory is that:', 'Aaron, because Otto''s convey- ance created a fee simple sub- ject to executory limitation in Aaron.', 'The rent increase from $200 to $400 is unconscionable and will shock the conscience of the court. 390 PROPERTY', 'The fact that Tina would have to pay double the rental rate charged to other tenants violates the implied agreement that rent- als for similar apartments be comparable.', 'The doctrine of retaliatory evic- tion is part of the law of this jurisdiction.', 'D', '', '', 0, ''),
('805', 'mbe', 'mbe_0805', 'prompt_1119', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '16', '', '011ie owned Blackacre, a one-acre tract of land, in fee simple absolute. How- ever, Paul was in adverse possession of Blackacre. During Paul''s adverse possession, 011ie gave Agnes oral per- mission to use the south forty feet along Blackacre as a road to reach Whiteacre, a tract of Agnes'' land. During all times relevant to this question, Agnes regu- larly used Blackacre as a road to reach Whiteacre from the public highway. A few years later, Paul quit possession of Blackacre without gaining title by adverse possession. Agnes continued to use the south forty feet along Black- acre from the time of her original use for a sufficiently long period of time to gain an easement by prescription. All of this use was accomplished without further communication between Agnes and 011ie. 011ie then blocked the road on the south forty feet along Blackacre and has refused to permit Agnes'' further use. Agnes then sued to determine her continued use of the road. In that law- suit, Agnes should: Q 0 m', 'Win, because her use was ad- verse to Paul and once adversely begun, it continued in that man- ner until some affirmative show- ing of a change.', 'Win, because Agnes made no attempt to renew 011ie''s permis- sion after Paul quit possession of Blackacre. PROPERTY 391 Questions 17 —18 are based on the following facts: Two sisters, Alice and Betty, contributed one-half of the purchase price of Yellow- acres, a 50-acre tract of land. They held Yel- lowacres together as joint tenants. Five years after the original purchase, Alice proposed that the two sisters develop Yellowacres as a retail shopping center. Betty did not want to do so. She orall', 'Lose, because her use was per- missive.', 'Lose, because there is no evi- dence that she continued to adversely use Blackacre for the required period after Paul quit Blackacre.', 'C', '', '', 0, ''),
('806', 'mbe', 'mbe_0806', 'prompt_1120', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '17', '', 'In an appropriate lawsuit to determine Sam and Betty''s respective interests in Yellowacres, if Sam is adjudicated to be the owner of the western 25 acres of Yellowacres, the most likely reason for the judgment will be that:', 'Betty''s actions during Alice''s life has estopped her from asserting title to the western one-half of Yellowacres.', 'The joint tenancy was terminated by the oral agreement of Alice and Betty at the time it was made. 392 PROPERTY "CP 0 m', 'Betty had a fiduciary obligation to Sam by reason of her be- ing named executrix of Alice''s will.', 'The close blood relationship be- tween Alice and Betty removes the necessity to comply with the Statute of Frauds.', 'A', '', '', 0, ''),
('807', 'mbe', 'mbe_0807', 'prompt_1121', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '18', '', 'In an appropriate lawsuit to determine Sam and Betty''s respective interests in Yellowacres, if Betty is adjudicated to be the sole owner of Yellowacres, the most likely reason for the judgment will be that:', 'The record title of the joint ten- ancy to Yellowacres can only be changed by a duly recorded instrument.', 'The Statute of Frauds prevents the proof of Betty and Alice''s oral agreement.', 'Alice could not unilaterally sever the joint tenancy.', 'Betty''s nomination as executrix of Alice''s estate does not prevent her from asserting her claim against Sam.', 'B', '', '', 0, ''),
('808', 'mbe', 'mbe_0808', 'prompt_1122', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '19', '', 'Baker and Selwyn entered into a valid, enforceable written contract in which Baker agreed to buy and Selwyn agreed to sell Orangeacre, Selwyn''s residence. The contract contained a provision al- lowing Selwyn the right to remain in residence of Orangeacre for 30 days before relinquishing possession. The closing took place as scheduled; title passed to Baker and Selwyn remained in possession. A week later, however, the house Selwyn was scheduled to move into was destroyed. At the end of the 30-day period, Selwyn refused to leave Orangeacre. Instead, Selwyn tendered to Baker a monthly rental pay- ment in excess of the fair rental value of Orangeacre. Baker refused the rent and sued to gain immediate possession of Orangeacre. There is no law of this jurisdiction dealing with this situation and the contract is similarly silent. The landlord-tenant law of this jurisdiction requires a 30-day notice by the landlord before he can evict a tenant. Baker did not give the 30-day statutory notice. Baker''s best legal argument in support of his action for immediate possession is that Selwyn is a:', 'Licensee.', 'Tenant at sufferance.', 'Della, because she is a remote grantee — not a direct grantee of Oliver Wendell.', 'Della, because she did not re- ceive a deed containing a restric- tive covenant.', 'A', '', '', 0, ''),
('809', 'mbe', 'mbe_0809', 'prompt_1123', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '20', '', 'Assume for this question only, that Della, a purchaser from Beth, has begun construction of a multi-family apart- ment building on her lot and that Abby sues to prevent Della''s apartment build- ing. Who will prevail in this lawsuit?', 'Carol''s proposed use will allow a sufficient diversity in economic classes in the vicinity to satisfy the requirements of the Equal Protection clause of the Constitu- tion.', 'Abby, because the apartment building will lower Abby''s land value. 394 PROPERTY Q', 'There has been an insufficient showing that the common de- velopment scheme applied to the entire subdivision.', 'Restrictive equitable servitudes bind only those in privity with the original covenanting par- ties.', 'A', '', '', 0, ''),
('810', 'mbe', 'mbe_0810', 'prompt_1124', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '23', '', 'Maria owned three condos in Condo Heaven, numbers 6, 7 and 21. The price and fair market value of condos 6 and 7 was $50,000, and number 21, $75,000. Nellie was interested in purchasing a condo in Condo Heaven but couldn''t decide between #6 or #7. Therefore, Nellie gave Maria $50,000 and Ma- ria prepared and executed a deed to Nellie for a condo in Condo Heaven, complete in every way except that the unit number was left blank. Maria told Nellie to fill in unit #6 or #7 as she wished and then Nellie should record the deed. The next day, Nellie went to Condo Heaven, filled in unit #21 in the deed and recorded the deed. In an action by Maria to rescind the transaction, if Maria loses, the most likely reason for that judgment is that:', 'The necessity for certainty in land title records controls.', 'The agency implied to complete the deed cannot be restricted by the oral understanding. PROPERTY 395 LLI 0- 0 ce CL', 'The recordation of the deed precludes any questioning of the deed in its recorded form.', 'Maria''s casual business practices caused her loss.', 'B', '', '', 0, ''),
('811', 'mbe', 'mbe_0811', 'prompt_1125', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '24', '', 'In 1980, Harold willed Beigeacres as follows: "To my daughter, Dolly, and at her death to those of Dolly''s chil- dren who survive her, provided, however, that no such child of Dolly shall have the power to con- vey, sell or mortgage such child''s interest prior to attaining the age of 30 years; and if any such child of Dolly shall not comply with this provision then that child''s interest shall determine and pass to the remaining children of Dolly alive at that time, share and share alike." Harold''s 1980 will devised Whiteacres to his son, Solomon, in an identical manner. The residuary clause in the 1980 will gave the residual estate to Harold''s two children, Dolly and Solo- mon, equally. In 1990, Harold died sur- vived by Dolly and Solomon and their two children each. Since 1990, Dolly has had one additional child. In an action to determine the property rights in Beigeacres, it was alleged that the gifts to Harold''s grandchildren were void and that the interests in Beigeacres, after Dolly''s children''s life estates passed to Harold''s children, passed absolutely under the residuary clause of the will. Assuming a properly instituted action with all parties represented, the judge should decide that:', 'The attempted gifts to the grand- children are void as restraints on alienation.', 'The attempted gifts to the grand- children are void under the Rule Against Perpetuities.', 'The attempted gifts to the grand- children are valid except for the provisions against sale, convey- ance or mortgage.', 'The attempted gifts to the grand- children are entirely valid and will be enforced as written. 396 PROPERTY ''CP 0 m', 'C', '', '', 0, ''),
('812', 'mbe', 'mbe_0812', 'prompt_1126', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '26', '', 'In 1991, Wilma conveyed Redacres as follows: "To my friend Fred for life and then to Fred''s two children, Bar- ney and Betty, and their heirs, provided that should any of them move to California, then that child''s interest to pass to the Red Cross." In 1991, Fred was alive and had two children, Barney and Betty. In an appro- priate action to determine the interests in Redacres, the gift to Fred''s children shall be held to be:', 'An executory interest.', 'Denied, since Thelma has sole title to the property.', 'Granted, because the tenancy by the entirety that was created by the deed was destroyed when Thelma abandoned Louis.', 'Granted, because the deed never created a tenancy by the en- tirety. PROPERTY 397 Questions 27 — 28 are based on the following facts: Bernie is the owner of Blueacres, a tract of land. In 1990, he contracted to sell Blueacres to Carla. Bernie and Carla executed an agree- ment for Carla to purchase Blueacres from Bernie for $50,000 cash. Assume Blueacres is located in a jurisdiction which recognizes the principle of equitable estoppel, but has no statute specifically dealing with these problems.', 'B', '', '', 0, ''),
('813', 'mbe', 'mbe_0813', 'prompt_1127', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '28', '', 'Assume for this question only, that Carla dies before the real estate clos- ing and her will gives her real property to Ricky and her personal property to Paula. Assume further, that the contract is otherwise fully performed. Which statement is most correct?', 'Ricky has the right to specifically perform the contract.', 'Peter is entitled to the $50,000 on closing since equitable conver- sion applies here.', 'Is enforceable, because no ambi- guity appears on the face of the deed.', 'Is sufficient, if Bill paid consid- eration.', 'A', '', '', 0, ''),
('814', 'mbe', 'mbe_0814', 'prompt_1128', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '29', '', 'The legal description of the portion of Wanda''s ranch given to Bill:', 'Insufficient, because it contains no description by metes and bounds.', 'Insufficient, because the acreage given is inaccurate.', 'Insufficient, because a grantor cannot convey more than she owns.', 'Sufficient, because the discrep- ancy in area is not fatal.', 'A', '', '', 0, ''),
('815', 'mbe', 'mbe_0815', 'prompt_1129', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '31', '', 'Ethel was the fee simple owner of Weed- acres (a vacant tract of land). Weedacres was located adjacent to Hedgeacres, a tract of land with a house and barn located on it and owned in fee simple by Fred. In 1990, Ethel began digging a foundation for a building on Weedacres to be located near the property line with Hedgeacres. Ethel''s digging caused the barn and land on Hedgeacres to collapse due to earth movement. In a lawsuit by Fred against Ethel for damages to his barn and land, due to Ethel''s excava- tion, the prevailing party should be: 399 PROPERTY', 'Fred, because he has an absolute right to lateral support of his land.', 'Fred, unless the weight of the barn contributed to the damage.', 'Ethel, but only if she was negli- gent in her excavation.', 'Ethel, unless her excavation would have caused the same damage to unimproved land, or she was negligent.', 'D', '', '', 0, ''),
('816', 'mbe', 'mbe_0816', 'prompt_1130', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '32', '', 'Francisco owned Farmacres (a tract of land) in fee simple absolute. He con- veyed it "to Gilbert for life, and then to the children of Helen in fee simple." At the time of the conveyance, both Gilbert and Helen were alive; neither had any children. What interest, if any, was created in Helen''s unborn children at the time of the conveyance?', 'A vested remainder, subject to partial divestment.', 'A contingent remainder.', 'An executory interest.', 'None. Questions 33 — 34 are based on the following facts: Quintin was the owner of Sandacres (a large tract of undeveloped land) in fee simple absolute. In 1970, he subdivided Sandacres into 3 parcels, #1-3. Quintin conveyed lot #1 to Rhoda, lot #2 (the middle lot) to Susan and lot #3, he retained as vacant land for speculation. Rhoda and Susan built houses and swimming pools on their lots. The land around Sandacres was undeveloped, unim- proved and unzoned. After their houses were built, Rhoda', 'B', '', '', 0, ''),
('817', 'mbe', 'mbe_0817', 'prompt_1131', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '33', '', 'If Susan sues Rhoda to enjoin Rhoda from interfering with Susan''s contin- ued use of the common sewer line, the prevailing party will be:', 'Susan, if, and only if, she was misled by Quintin''s failure to complain when she was building her pool.', 'Rhoda, because the continued use of the common easement after a material change in circumstances would diminish the fair market value of the lots, without a cor- responding and commensurate increase in value.', 'Susan, because an incorporeal hereditament lies in grant and cannot be terminated without a writing.', 'Susan, because the termination of the necessity for the ease- ment which had been created by express grant does not affect the rights in the easement.', 'D', '', '', 0, ''),
('818', 'mbe', 'mbe_0818', 'prompt_1132', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '35', '', 'In a lawsuit by Victoria against Wilma to establish that Victoria has title to Plantacres, if Wilma loses it will be because:', 'The events of January 1, 1990 were a conditional delivery to a grantee without an escrow.', 'Wilma is a donee and not a bona fide purchaser under the record- ing act.', 'The events of January 1, 1990 were insufficient to constitute a valid delivery.', 'Wilma did not record her deed as required by the recording act.', 'C', '', '', 0, ''),
('819', 'mbe', 'mbe_0819', 'prompt_1133', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '36', '', 'In a lawsuit by Victoria against Wilma to establish that Victoria has title to Plantacres, if Victoria loses, it will be because:', 'Parol evidence is inadmissible to prove an oral condition rebutting valid delivery.', 'As between the parties to a trans- action, recording is not required to transfer title after a valid de- livery.', 'Wilma has proven that Victoria intended to part with Plantacres irrevocably.', 'This is a donative escrow, which creates consideration for the transfer through the relationship of blood or marriage. 402 PROPERTY Q', 'C', '', '', 0, ''),
('820', 'mbe', 'mbe_0820', 'prompt_1134', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '38', '', 'Yvette conveys Bambooacres (a tract of land) to Zerlina by warranty deed as a gift for Zerlina''s birthday. One year later, Yvette conveys the same property, Bambooacres, to Abelia for $100,000. Abelia is without constructive or actual knowledge of the prior deed to Zerlina. Abelia records her deed to Bamboo- acres first. Abelia receives the property pursuant to the recording act in this jurisdiction. If Zerlina sues Yvette for having lost the property to Abelia, the outcome of Zerlina''s lawsuit against Yvette will depend on:', 'Will must pay both the principal and interest.', 'Xerxes must pay both principal and interest.', 'Whether the jurisdiction views title covenants as personal or running with the land.', 'Xerxes must pay the principal and Will must pay the interest. 403 PROPERTY 0 ce a_', 'A', '', '', 0, ''),
('821', 'mbe', 'mbe_0821', 'prompt_1135', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '39', '', 'Benjy owned Bushacres (a tract of land) in fee simple absolute. He conveyed Bushacres in 1954 "to Carla and Dan, as wife and husband." In this jurisdiction, Benjy''s conveyance would be sufficient to create a tenancy by the entirety. Thereafter, Carla conveyed by a deed in valid form and delivery "my undi- vided one-half interest in Bushacres" to Esther. Carla died one year later. If Esther sues Dan to quiet title in himself and herself as co-owners of Bushacres, she will:', 'Not prevail, unless Carla and Dan were not legally married according to the laws in this jurisdiction during the relevant times in this problem.', 'Not prevail, because he is the sole owner of Bushacres. Questions 40 — 41 are based on the following facts: In 1978, Fiona owned Palmacres (a tract of land) in fee simple absolute. In that year, she executed and delivered to Gus a quitclaim deed which purported to convey to Gus all Fiona''s interest and title in Palmacres. Gus accepted the deed and placed it in his bank safe deposit box. In satisfaction of a prior debt she owed to Hal, Fiona executed and delivered a warranty deed to Hal also pur-', 'Prevail, if, and only if, Esther had no actual or constructive notice of the deed to Dan and Carla.', 'Prevail, since Esther and Dan own Bushacres as tenants in common.', 'A', '', '', 0, ''),
('822', 'mbe', 'mbe_0822', 'prompt_1136', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '40', '', 'The recording act in this jurisdiction may be: I. Race II. Race-Notice III. Notice', 'I or II.', 'II or III.', 'I or III.', 'None of the above. 404 PROPERTY Q', 'B', '', '', 0, ''),
('823', 'mbe', 'mbe_0823', 'prompt_1137', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '41', '', 'Which is the most accurate statement regarding the conflicting claims to Palmacres of Gus and Hal?', 'Valid contingent remainder.', 'Gus'' failure to record until after Hal, equitably estops Gus from asserting title against Hal (but not against Fiona).', 'The outcome will turn on wheth- er Hal paid value within the meaning of the recording act.', 'None of the above.', 'C', '', '', 0, ''),
('824', 'mbe', 'mbe_0824', 'prompt_1138', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '45', '', 'Assume for this question only, that in 1989 Max sued Oliver claiming that Max owned Pineacres and that Oliver did not. The prevailing party owning Pineacres should have been:', 'Max, because Oliver was not a bona fide purchaser for value. 406 PROPERTY', 'Max, because he was a purchaser for full market value and had no actual or constructive notice of the deed to Oliver.', 'Oliver, because Oliver had no notice of Max''s interest in Pine- acres.', 'Oliver, because Oliver''s deed was the first recorded.', 'A', '', '', 0, ''),
('825', 'mbe', 'mbe_0825', 'prompt_1139', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '47', '', 'Irene leased her house and surround- ing yard to Juan for fifteen years. The lease contained a clause prohibiting Juan from assigning his interest in the lease. Kris has approached Juan about subletting the house and yard to him. May Juan do so?', 'Yes, because restraints on alien- ation are invalid.', 'Yes, because a lease term pro- hibiting assignments is strictly construed.', 'No, because the term "assign- ment" includes "subleasing" and vice versa.', 'No, because a tenant can never assign or sublease without the landlord''s permission, since to do so would be to impair the landlord''s security interest in the property. Q -0 XI0 13 m -I -<', 'B', '', '', 0, ''),
('826', 'mbe', 'mbe_0826', 'prompt_1140', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '48', '', 'Ignatz owned Grassacres (a tract of land) in fee simple absolute. He con- veyed it "to Jenny, her heirs and assigns while the property is used for ranch purposes; then to Kelly and his heirs forever. Assume the common law Rule Against Perpetuities applies to this con- veyance. Kelly''s interest in Grassacres as a result of this conveyance is best described as:', 'A possibility of reverter.', 'A right of entry (or power of Questions 49 — 51 are based on the termination). following facts:', 'An executory interest.', 'Nothing. Terah leased a single family residence from Utley for a term of four years. Without Utley''s knowledge, Terah, a skilled carpen- ter, installed three beautiful, hand-crafted floor-to-ceiling oak bookcases, which he se- curely bolted to the wall next to the fireplace. He also replaced the old wooden steps lead- ing to the front door with a new, larger and more efficient set of stone steps and he added a banister. At the end of his lease, Terah re- moved the bookcases, leaving several deep', 'D', '', '', 0, ''),
('827', 'mbe', 'mbe_0827', 'prompt_1141', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '49', '', 'In an action for damages to the house brought by Utley against Terah for the removal of the bookcases, the prevail- ing party will be:', 'Terah, but only if the bookcases were used in his trade or busi- ness.', 'Terah, but only if the jurisdiction follows the modern trend in the law of fixtures.', 'Terah, because the bookcases are considered personal property.', 'Utley, because the bookcases are considered real property.', 'D', '', '', 0, ''),
('828', 'mbe', 'mbe_0828', 'prompt_1142', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '50', '', 'In an action by Terah against Utley to recover the cost of replacing the old front door steps, Terah will: 408 PROPERTY Q', 'Win, because he has created an improvement to Utley''s freehold interest in the property.', 'Win, but only if he added value of the improvement will last be- yond the term of Terah''s lease.', 'Lose, if the jurisdiction preserves the common law doctrine of per- missive waste.', 'Lose, if the jurisdiction preserves the common law doctrine of ameliorative waste.', 'D', '', '', 0, '')
